"""Contract checks on the SCORED calls themselves (FIXED, not editable; TRUSTED).

Only the linear-attention task needs these: there the editable region is the
token mixer, so it runs inside every scorer.  (The hybrid task's scorers replay
the recorded layer stack and never execute its region; `make_checker` returns
None there.)

Every scored forward can be routed through `Checker.logits`, which

* runs the forward ONCE and returns ITS logits -- the numbers that are scored
  are the numbers that were checked;
* causality (`causal_split=s`): re-runs the same batch with every token from
  position `s` on replaced, and requires the logits before `s` to be unchanged.
  The split is drawn per call by this process, so a mixer that reads ahead by
  any distance is caught on the positions just before the split, on the scored
  text itself (the training-time probe only ever saw random tokens);
* the fixed-memory contract (`contract_probe`): the training-time probe re-run
  here by trusted code -- every layer's mixer is re-run on its captured input
  in two halves, carrying only the state it returned (and the fixed front-end's
  convolution cache); the second half must reproduce the one-shot output, the
  state must fit the budget, and its size must be the same at 1x and 4x the
  training context.  (A per-scored-batch carry check at random splits was
  tried and dropped: at arbitrary, non-chunk-aligned split points the honest
  GSA / ABC kernels differ from their one-shot output by 5-6% relative in bf16,
  and a 5-token piece trips fla's own shape check.)
* no cross-call state: each mixer's `forward` is wrapped so that a call which
  changes the mixer's own attributes, parameters, buffers or submodules (an
  in-place update, a cache kept on the instance) is an error.  Together with
  the static guard (no attribute writes or in-place mutation outside
  `__init__`, no closures, no mutable defaults or class-level containers) this
  is what makes each scored call a fresh function of its inputs.

A violation raises `fixed_loader.ScoringError`; the scorer then prints INVALID
and exits non-zero, so the run records no metric.
"""
import numpy as np
import torch

from fixed_loader import ScoringError

CAUSAL_TOL = 1e-2          # absolute, on logits (the training-time probe's threshold)


def _fp_val(v):
    if torch.is_tensor(v):
        return ("T", id(v), v._version, v.data_ptr() if v.numel() else 0,
                str(v.dtype), tuple(v.shape))
    if isinstance(v, (list, tuple)):
        return ("L", id(v), len(v), tuple(_fp_val(e) if torch.is_tensor(e) else id(e)
                                          for e in v))
    if isinstance(v, dict):
        return ("D", id(v), len(v), tuple((str(k), id(e)) for k, e in v.items()))
    if isinstance(v, (set, frozenset)):
        return ("S", id(v), len(v))
    if isinstance(v, (bool, int, float, str, type(None))):
        return ("V", v)
    return ("O", id(v))


def _fingerprint(module):
    out = []
    for name, m in module.named_modules():
        d = {}
        for k, v in m.__dict__.items():
            if k in ("_parameters", "_buffers", "_modules"):
                continue
            d[k] = _fp_val(v)
        for k, p in m._parameters.items():
            d["P:" + k] = _fp_val(p)
        for k, b in m._buffers.items():
            d["B:" + k] = _fp_val(b)
        d["M"] = tuple((k, id(c)) for k, c in m._modules.items())
        out.append((name, d))
    return out


def _flatten_state(s):
    if s is None:
        return []
    if torch.is_tensor(s):
        return [s]
    if isinstance(s, dict):
        s = list(s.values())
    if isinstance(s, (tuple, list)):
        flat = []
        for e in s:
            flat.extend(_flatten_state(e))
        return flat
    raise ScoringError("the mixer state must be tensors held in a tuple/list; got %r"
                       % (type(s),))


class Checker:
    def __init__(self, model, mod, seed=20260926):
        self.model = model
        self.attns = [blk.attn for blk in model.transformer.h]
        self.vocab = int(model.config.vocab_size)
        self.budget = int(mod.FLA_STATE_BUDGET)
        self.carry_tol = float(mod.FLA_STATE_CARRY_TOL)
        self.rng = np.random.default_rng(seed)
        self.gen = torch.Generator(device="cpu").manual_seed(seed)
        self.max_carry_err = 0.0
        self.max_causal_delta = 0.0
        self.n_carry = 0
        self.n_causal = 0
        self.state_sizes = set()
        self.routing = None          # per-layer counts, for mixers exposing a router
        self.routing_calls = 0
        m0 = self.attns[0].mixer
        self._has_router = (isinstance(getattr(m0, "gate", None), torch.nn.Linear)
                            and isinstance(getattr(m0, "num_memories", None), int)
                            and isinstance(getattr(m0, "topk", None), int))
        for attn in self.attns:
            mixer = attn.mixer
            orig = mixer.forward

            def checked(*a, _orig=orig, _m=mixer, **k):
                before = _fingerprint(_m)
                out = _orig(*a, **k)
                if _fingerprint(_m) != before:
                    raise ScoringError(
                        "the mixer changed its own state (an attribute, parameter, buffer "
                        "or submodule) during a call; scored calls must not carry state "
                        "between them")
                return out

            mixer.forward = checked

    # ── the scored forward ────────────────────────────────────────────────
    @torch.no_grad()
    def logits(self, x, ctx, carry=False, causal_split=None, full=True, split=None):
        cap = {}
        handles = []
        route = (not carry) and self.routing_calls < 20 and self._has_router
        if route:
            self.routing_calls += 1
            for i, attn in enumerate(self.attns):
                def rhook(_mod, args, out, _i=i):
                    self._route(_i, _mod.mixer, args[0].detach())
                handles.append(attn.register_forward_hook(rhook))
        if carry:
            for i, attn in enumerate(self.attns):
                def hook(_mod, args, out, _i=i):
                    cap[_i] = (args[0].detach(), out.detach())
                handles.append(attn.register_forward_hook(hook))
        try:
            with ctx:
                lg, _ = self.model(x, x) if full else self.model(x)
        finally:
            for h in handles:
                h.remove()
        if carry:
            self._carry(cap, ctx, split)
        if causal_split is not None and full:
            self._causal(x, lg, int(causal_split), ctx)
        return lg

    def random_split(self, lo, hi):
        """A split point in [lo, hi), drawn by this process."""
        return int(self.rng.integers(lo, max(lo + 1, hi)))

    # ── checks ────────────────────────────────────────────────────────────
    def _carry(self, cap, ctx, split=None):
        for i, attn in enumerate(self.attns):
            xin, ref = cap[i]
            T = xin.shape[1]
            if T < 4:
                continue
            s = split if split is not None else T // 2
            with ctx:
                _, st, cv = attn._mix(xin[:, :s], state=None, conv_state=None,
                                      return_state=True)
                o2, _, _ = attn._mix(xin[:, s:], state=st, conv_state=cv,
                                     return_state=True)
            r = ref[:, s:].float()
            err = (o2.float() - r).abs().max().item() / (r.abs().max().item() + 1e-6)
            size = -(-sum(t.numel() for t in _flatten_state(st)) // xin.shape[0])
            if not np.isfinite(err):
                raise ScoringError("the fixed-memory check produced non-finite values")
            self.max_carry_err = max(self.max_carry_err, err)
            self.state_sizes.add(size)
            self.n_carry += 1
            if err >= self.carry_tol:
                raise ScoringError(
                    "the mixer does not carry its whole state on a scored call (layer %d, "
                    "T=%d, split %d): the second piece moved by %.6f relative, above %s"
                    % (i, T, s, err, self.carry_tol))
            if size > self.budget:
                raise ScoringError("on a scored call the mixer keeps %d state scalars per "
                                   "sequence, above the budget of %d" % (size, self.budget))
            if len(self.state_sizes) != 1:
                raise ScoringError("the recurrent state is not of fixed size across scored "
                                   "calls: %r scalars per sequence" % sorted(self.state_sizes))

    def _route(self, i, mixer, xin):
        with torch.no_grad():
            sel = torch.topk(torch.softmax(mixer.gate(xin).float(), -1), mixer.topk, -1)[1]
            cnt = torch.bincount(sel.flatten(), minlength=mixer.num_memories).cpu()
        if self.routing is None:
            self.routing = {}
        self.routing[i] = self.routing.get(i, 0) + cnt

    def _causal(self, x, lg, s, ctx):
        if s <= 0 or s >= x.shape[1]:
            return
        x2 = x.clone()
        x2[:, s:] = torch.randint(0, self.vocab, (x.shape[0], x.shape[1] - s),
                                  generator=self.gen).to(x.device)
        with ctx:
            lg2, _ = self.model(x2, x2)
        d = 0.0
        for a in range(0, s, 1024):
            b = min(a + 1024, s)
            d = max(d, (lg[:, a:b].float() - lg2[:, a:b].float()).abs().max().item())
        self.max_causal_delta = max(self.max_causal_delta, d)
        self.n_causal += 1
        if not np.isfinite(d) or d >= CAUSAL_TOL:
            raise ScoringError(
                "the model is not causal on a scored call: replacing the tokens from "
                "position %d on moved the logits before it by %r" % (s, d))

    def summary(self):
        line = ("SCORED_CHECKS: carry_calls=%d, max_carry_rel_err=%.6f, causal_calls=%d, "
                "max_causal_delta=%.6f, state_floats=%s"
                % (self.n_carry, self.max_carry_err, self.n_causal, self.max_causal_delta,
                   ",".join(str(s) for s in sorted(self.state_sizes)) or "-"))
        if self.routing:
            parts = []
            for i in sorted(self.routing):
                c = self.routing[i].double()
                parts.append("L%d=%s" % (i, "/".join("%.3f" % v for v in (c / c.sum()).tolist())))
            line += "\nROUTING_FRACTIONS: " + " ".join(parts)
        return line

    # the training-time probe, re-run here on random tokens at 1x and 4x the
    # training context (B=2): carry + budget + one fixed size across lengths
    def contract_probe(self, block, ctx, device):
        for mult in (1, 4):
            x = torch.randint(0, self.vocab, (2, block * mult), generator=self.gen).to(device)
            self.logits(x, ctx, carry=True, causal_split=None, full=False, split=block * mult // 2)


def make_checker(model, mod, hybrid, seed=20260926):
    if hybrid or not hasattr(model.transformer.h[0].attn, "mixer"):
        return None
    return Checker(model, mod, seed=seed)

